DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.record_coach_guideline_overrides()'::regprocedure) INTO def; IF position('''send'',''reschedule'',''resend'',''use_instead'',''add_alongside''' in def)=0 THEN RAISE EXCEPTION 'Expected acknowledgement validator not found'; END IF; def:=replace(def,'''send'',''reschedule'',''resend'',''use_instead'',''add_alongside''','''send'',''reschedule'',''resend'',''use_instead'',''add_alongside'',''edit_day'''); EXECUTE def; END $$;